CREATE OR REPLACE FUNCTION crowd_observation.guard_internal(p_action text DEFAULT 'control'::text, p_task bigint DEFAULT NULL::bigint, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 u uuid:=auth.uid(); p crowd_v4.participants; c crowd_v4.policy; s crowd_v4.safety;
 t timestamptz:=clock_timestamp(); d date; caps jsonb; factor numeric; reason text; wait_until timestamptz;
 gap_seconds integer; configured_gap_ms integer; action_key text; admitted boolean:=false; owner uuid; result jsonb; batch_caps jsonb;
begin
 if u is null then raise exception 'login_required' using errcode='42501'; end if;
 if p_action is null or p_action not in ('control','search','detail','comment','scroll','captcha','rate_limit','profile') then raise exception 'invalid_action'; end if;
 action_key:=case when p_action='profile' then 'detail' else p_action end;
 -- One identity's admission decisions serialize with its quota/lease operations.
 select * into p from crowd_v4.participants where user_id=u for update;
 if p.status is distinct from 'approved' or p.consent is distinct from 'crowd-public-v4' then raise exception 'approval_required' using errcode='42501'; end if;
 select * into c from crowd_v4.policy where singleton;
 gap_seconds:=coalesce((select action_gap_seconds from crowd_v4.tasks where id=p_task and claimed_by=u and status='leased' and lease_until>t),c.gap_seconds);
 select task.action_gap_milliseconds into configured_gap_ms from crowd_v4.tasks task join crowd_v4.test_task_owners reservation on reservation.task_id=task.id and reservation.user_id=u where task.id=p_task and task.claimed_by=u and task.status='leased' and task.lease_until>t;
 if c.version is null then raise exception 'control_unavailable'; end if;
 insert into crowd_v4.safety(user_id) values(u) on conflict do nothing;
 select * into s from crowd_v4.safety where user_id=u for update;
 d:=(t at time zone 'Asia/Shanghai')::date;
 if d>s.day then s.day:=d; s.counts:='{"search":0,"detail":0,"comment":0,"scroll":0}'; end if;
 -- Server enrollment age, never a resettable client date. Future dates stay at 20%.
 factor:=least(1,0.2+greatest(0,floor(extract(epoch from t-p.joined_at)/86400))*0.8/6);
 caps:=jsonb_build_object('search',least(c.search_cap,coalesce((select task.daily_search_cap from crowd_v4.tasks task join crowd_v4.test_task_owners reservation on reservation.task_id=task.id and reservation.user_id=u where task.id=p_task and task.claimed_by=u and task.status='leased' and task.lease_until>t),greatest(1,floor(c.search_cap*factor)))),
 'detail',least(c.detail_cap,coalesce((select task.daily_detail_cap from crowd_v4.tasks task join crowd_v4.test_task_owners reservation on reservation.task_id=task.id and reservation.user_id=u where task.id=p_task and task.claimed_by=u and task.status='leased' and task.lease_until>t),greatest(1,floor(c.detail_cap*factor)))), 'comment',least(c.comment_cap*10,coalesce((select task.daily_comment_cap from crowd_v4.tasks task join crowd_v4.test_task_owners reservation on reservation.task_id=task.id and reservation.user_id=u where task.id=p_task and task.claimed_by=u and task.status='leased' and task.lease_until>t),greatest(1,floor(c.comment_cap*factor)))), 'scroll',greatest(1,floor(c.scroll_cap*factor)));
 -- Only the already-authorized original local batch may use its configured bounded detail ceiling.
 if p_task=19 then
  batch_caps:=crowd_v4.acceptance_supplement_view(p_task,u);
  if batch_caps->>'schema'='crowd-acceptance-batch-v1' and (batch_caps->>'remaining')::integer>0
   and exists(select from crowd_v4.tasks task where task.id=p_task and task.claimed_by=u and task.status='leased' and (p_action='control' or task.lease_until>t)) then
   caps:=jsonb_set(caps,'{detail}',to_jsonb(least(200,coalesce((select task.daily_detail_cap from crowd_v4.tasks task where task.id=p_task),c.detail_cap))));
   if batch_caps->>'installation_id'='3cde2858-39a5-42e1-b7ab-dd62053d2dac' then
    caps:=jsonb_set(caps,'{scroll}',to_jsonb(least(200,coalesce((select task.daily_detail_cap from crowd_v4.tasks task where task.id=p_task),c.detail_cap))));
   end if;
  end if;
 end if;
 if p_action in ('captcha','rate_limit') then
  if p_action='rate_limit' and exists(select from crowd_observation.recovery_controls r join crowd_v4.test_task_owners o on o.task_id=r.task_id and o.user_id=u join crowd_v4.tasks rt on rt.id=r.task_id join crowd_v4.proofs f on f.task_id=r.task_id and f.user_id=u and f.note_id=r.note_id where r.user_id=u and r.enabled and rt.claimed_by=u and rt.status='leased') and (s.cooldown_reason is null or s.cooldown_reason='rate_limit' or s.cooldown_until<=t) then
   update crowd_observation.recovery_controls r set failure_count=least(1000000,failure_count+1),last_signal_at=t,
    next_probe_at=greatest(next_probe_at,t+crowd_observation.recovery_delay(least(1000000,failure_count+1))),
    safety_deadline=greatest(next_probe_at,t+crowd_observation.recovery_delay(least(1000000,failure_count+1))),attempt=null,attempt_until=null,grant_task_ids=null,grant_bindings=null,last_result='rate_limit',last_attempt=null,last_response=null where r.user_id=u;
   select safety_deadline into s.cooldown_until from crowd_observation.recovery_controls where user_id=u;
   s.cooldown_reason:='rate_limit';
  elsif p_action='captcha' then
   update crowd_observation.recovery_controls set enabled=false,attempt=null,attempt_until=null,grant_task_ids=null,grant_bindings=null,last_result='captcha' where user_id=u;
   s.cooldown_until:=greatest(s.cooldown_until,t+interval '30 minutes'); s.cooldown_reason:='captcha';
  elsif s.cooldown_reason is distinct from 'captcha' or s.cooldown_until<=t then
   s.cooldown_until:=greatest(s.cooldown_until,t+interval '24 hours'); s.cooldown_reason:='rate_limit';
  end if;
 end if;
 -- Only a participant enrolled today has complete lifetime counts in this day.
 -- Older or cross-midnight histories cannot establish why an old rest began.
 if s.cooldown_reason='session_rest' and s.session_count=0 and s.cooldown_until>t
  and p.joined_at >= (d::timestamp at time zone 'Asia/Shanghai') and p.joined_at<=t
  and (select day from crowd_v4.safety where user_id=u)=d
  and (select coalesce(sum(value::integer),0) from jsonb_each_text(s.counts))<20 then
  wait_until:=least(s.cooldown_until,greatest(t,least(t,s.next_action)+interval '30 minutes'));
  if s.session_started=s.cooldown_until then s.session_started:=wait_until; end if;
  s.cooldown_until:=wait_until;
  wait_until:=null;
 end if;
 if s.cooldown_until>t then reason:=s.cooldown_reason; wait_until:=s.cooldown_until;
 elsif c.paused then reason:='global_pause'; wait_until:=t+interval '5 minutes';
 elsif s.next_action>t then reason:='action_gap'; wait_until:=s.next_action;
 end if;
 if p_action in ('search','detail','comment','scroll','profile') and reason is null then
  if not exists(select from crowd_v4.tasks where id=p_task and claimed_by=u and status='leased' and lease_until>t) then
   return jsonb_build_object('error','lease_expired');
  end if;
  if (s.counts->>action_key)::int >= (caps->>action_key)::int then
   reason:='action_budget'; wait_until:=(d+1)::timestamp at time zone 'Asia/Shanghai';
  else
   if s.session_count>0 and s.next_action+interval '30 minutes'<=t then
    s.session_count:=0; s.session_started:=t;
   end if;
   if s.session_count>=coalesce((select session_action_limit from crowd_v4.tasks where id=p_task and claimed_by=u and status='leased' and lease_until>t),20) or (s.session_count>0 and s.session_started+make_interval(secs=>coalesce((select session_window_seconds from crowd_v4.tasks where id=p_task and claimed_by=u and status='leased' and lease_until>t),1200))<=t) then
    if s.session_count>=coalesce((select session_action_limit from crowd_v4.tasks where id=p_task and claimed_by=u and status='leased' and lease_until>t),20) then
     s.session_started:=t+interval '30 minutes';
    else
     s.session_started:=greatest(t,least(t,s.next_action)+interval '30 minutes');
    end if;
    s.session_count:=0;
    s.cooldown_until:=s.session_started; s.cooldown_reason:='session_rest';
    reason:='session_rest'; wait_until:=s.cooldown_until;
   else
    if p_action='profile' and not exists(select from crowd_observation.profile_attempts a join crowd_observation.notes n using(author_id) where a.user_id=u and n.note_id=p_note and a.attempted_at>t-interval '1 minute') then raise exception 'profile_not_admitted'; end if; if p_action='detail' then
     if p_note is null or p_note !~ '^[a-f0-9]{24}$' then raise exception 'invalid_note'; end if;
     if exists(select from crowd_v4.proofs where note_id=p_note) and not exists(select from crowd_v4.tasks task join crowd_v4.receipts r on r.request=any(task.comment_repair_parents) and r.user_id=u and r.result->>'inserted'='true' where task.id=p_task and task.claimed_by=u and task.status='leased' and task.lease_until>t and task.comments_capture and r.payload->'record'->'standard'->>'note_id'=p_note) and not exists(select from crowd_v4.tasks rt join crowd_v4.test_task_owners ro on ro.task_id=rt.id and ro.user_id=u join crowd_v4.proofs f on f.task_id=rt.id and f.user_id=u and f.note_id=p_note where rt.id=p_task and rt.claimed_by=u and rt.status='leased' and rt.lease_until>t and rt.comments_capture and rt.received>=rt.target) then
      reason:='known_note';
     else
      -- Only reserve one requested ID, never expose another participant or proof.
      insert into crowd_v4.note_reservations(note_id,user_id,expires_at) values(p_note,u,t+interval '10 minutes')
      on conflict(note_id) do update set user_id=u,expires_at=t+interval '10 minutes'
       where crowd_v4.note_reservations.expires_at<=t or crowd_v4.note_reservations.user_id=u
      returning user_id into owner;
      if owner is null then reason:='note_busy'; end if;
     end if;
    end if;
    if reason is null then
     if s.session_count=0 then s.session_started:=t; end if;
     s.session_count:=s.session_count+1;
     s.counts:=jsonb_set(s.counts,array[action_key],to_jsonb((s.counts->>action_key)::int+1));
     -- Sample ONCE per admitted action and persist; polling never redraws the wait.
     s.next_action:=case when configured_gap_ms is not null then t+configured_gap_ms*interval '1 millisecond' else t+make_interval(secs=>gap_seconds+floor(random()*least(16,floor(gap_seconds/2.0)::int+1))::int) end;
     admitted:=true;
    end if;
   end if;
  end if;
 end if;
 update crowd_v4.safety set day=s.day,counts=s.counts,next_action=s.next_action,cooldown_until=s.cooldown_until,
 cooldown_reason=s.cooldown_reason,session_count=s.session_count,session_started=s.session_started where user_id=u;
 -- Expired reservations are not retained as a browsing history.
 delete from crowd_v4.note_reservations where expires_at<t-interval '1 day';
 result:=jsonb_build_object('observations',1,'relevance_revision',1,'version',c.version,'ttl_ms',600000,'paused',c.paused,'allowed',admitted,
 'reason',reason,'wait_ms',greatest(0,ceil(extract(epoch from (wait_until-t))*1000)),
 'action_wait_ms',greatest(0,ceil(extract(epoch from (s.next_action-t))*1000)),'gap_ms',coalesce(configured_gap_ms,gap_seconds*1000),'caps',caps,'counts',s.counts,'session_count',s.session_count);
 result:=result||jsonb_build_object('recovery_enabled',exists(select from crowd_observation.recovery_controls r where r.user_id=u and r.enabled),'recovery_wait_ms',(select greatest(0,ceil(extract(epoch from r.next_probe_at-t)*1000)) from crowd_observation.recovery_controls r where r.user_id=u and r.enabled));
 return result;
end $function$

CREATE OR REPLACE FUNCTION crowd_observation.validate_note(p_record jsonb, p_task bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s jsonb; e jsonb; t crowd_v4.tasks; capture timestamptz; c jsonb; item jsonb; seen text[]:=array[]::text[];
begin
 select * into t from crowd_v4.tasks where id=p_task;
 s:=p_record->'standard'; e:=p_record->'evidence';
 if jsonb_typeof(p_record) is distinct from 'object' or p_record->>'schema_version' is distinct from '4'
 or jsonb_typeof(s) is distinct from 'object' or jsonb_typeof(e) is distinct from 'object' or jsonb_typeof(p_record->'extra') is distinct from 'object'
 or octet_length(p_record::text)>180000 or s->>'platform' is distinct from 'xiaohongshu'
 or coalesce(s->>'note_id','') !~ '^[a-f0-9]{24}$' or s->>'url' is distinct from ('https://www.xiaohongshu.com/explore/'||(s->>'note_id'))
 or jsonb_typeof(s->'title') is distinct from 'string' or length(s->>'title')>300
 or jsonb_typeof(e->'text') is distinct from 'string' or length(e->>'text')>24000 or (length(e->>'text')=0 and length(s->>'title')=0 and p_record->'extra'->>'media_present' is distinct from 'true')
 or e->>'source' is distinct from 'rendered_public_dom' then return jsonb_build_object('error','invalid_record'); end if;
 if not (s ?& array['platform','note_id','url','title','captured_at','published_at','author_display','like_count','collect_count','comment_count'])
 or jsonb_typeof(s->'author_display') not in ('string','null') or length(s->>'author_display')>100
 or jsonb_typeof(s->'published_at') not in ('string','null')
 or (s->>'published_at' is not null and s->>'published_at' !~ '^20[0-9]{2}-[0-9]{2}-[0-9]{2}$')
 or e->>'parser_version' is null or e->>'parser_version' !~ '^4\.[0-9]+\.[0-9]+$'
 or jsonb_typeof(e->'original_length') is distinct from 'number' or coalesce(e->>'original_length','') !~ '^[0-9]{1,8}$'
 or jsonb_typeof(e->'truncated') is distinct from 'boolean'
 or jsonb_typeof(p_record->'extra'->'author_opinion_quotes') is distinct from 'array'
 then return jsonb_build_object('error','invalid_record'); end if;
 if (e->>'original_length')::int<length(e->>'text') or jsonb_array_length(p_record->'extra'->'author_opinion_quotes')>30
 or exists(select 1 from jsonb_array_elements(p_record->'extra'->'author_opinion_quotes') q where jsonb_typeof(q)<>'string' or strpos(e->>'text',q#>>'{}')=0)
 or exists(select 1 from jsonb_each(s) a(key,value) where key in ('like_count','collect_count','comment_count','view_count') and
   (jsonb_typeof(value) not in ('null','number') or (value<>'null'::jsonb and value::text !~ '^[0-9]{1,10}$')))
 then return jsonb_build_object('error','invalid_record'); end if;
 if exists(select 1 from jsonb_each(s) a(key,value) where key in ('like_count','collect_count','comment_count','view_count') and value<>'null'::jsonb and value::text::numeric>2147483647)
 then return jsonb_build_object('error','invalid_record'); end if;
 begin perform (s->>'published_at')::date; exception when others then return jsonb_build_object('error','invalid_published_date'); end;
 begin capture:=(s->>'captured_at')::timestamptz; exception when others then return jsonb_build_object('error','invalid_timestamp'); end;
 if capture is null or capture>now()+interval '5 minutes' or capture<now()-interval '24 hours' then return jsonb_build_object('error','invalid_timestamp'); end if;
 if not exists(select 1 from jsonb_array_elements_text(t.anchor_terms) a(term) where length(term)>=2 and
 strpos(lower(regexp_replace((s->>'title')||' '||(e->>'text'),'[[:space:][:punct:]]','','g')),lower(regexp_replace(term,'[[:space:][:punct:]]','','g')))>0)
 then return jsonb_build_object('error','unrelated_note'); end if;

 if p_record->'extra'->'author' is not null and p_record->'extra'->'author'<>'null'::jsonb then
  if jsonb_typeof(p_record->'extra'->'author')<>'object'
   or coalesce(p_record#>>'{extra,author,id}','') !~ '^[a-f0-9]{24}$'
   or p_record#>>'{extra,author,url}' is distinct from ('https://www.xiaohongshu.com/user/profile/'||(p_record#>>'{extra,author,id}'))
  then return jsonb_build_object('error','invalid_record'); end if;
 end if;
 c:=p_record#>'{extra,comments}';
 if c is not null then
  if jsonb_typeof(c->'items') is distinct from 'array' or c->>'coverage' is distinct from 'visible_loaded_only'
   or c->>'complete' is distinct from 'false' or jsonb_typeof(c->'truncated') is distinct from 'boolean'
  then return jsonb_build_object('error','invalid_record'); end if;
  if jsonb_array_length(c->'items')>50 or c->>'captured_count' is distinct from jsonb_array_length(c->'items')::text then return jsonb_build_object('error','invalid_record'); end if;
  for item in select value from jsonb_array_elements(c->'items') loop
   if coalesce(item->>'key','') !~ '^comment-[1-9][0-9]*$' or item->>'key'=any(seen)
    or (item->>'parent_key' is not null and not(item->>'parent_key'=any(seen)))
    or jsonb_typeof(item->'text') is distinct from 'string' or length(item->>'text') not between 1 and 2000
    or coalesce(item->>'original_length','') !~ '^[0-9]{1,8}$'
    or jsonb_typeof(item->'truncated') is distinct from 'boolean'
   then return jsonb_build_object('error','invalid_record'); end if;
   if (item->>'original_length')::int<length(item->>'text') then return jsonb_build_object('error','invalid_record'); end if;
   seen:=array_append(seen,item->>'key');
  end loop;
 end if;
 return '{}'::jsonb;
end $function$

CREATE OR REPLACE FUNCTION public.crowd_v4_admin(p_action text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t crowd_v4.tasks; f crowd_v4.proofs; u uuid; n int; result jsonb; quote text; decision text;
begin
 if p_action='publish' and jsonb_typeof(p_payload->'anchor_terms')='array' then
 p_payload:=jsonb_set(p_payload,'{anchor_terms}',crowd_observation.terms(p_payload->>'store_name',p_payload->'anchor_terms'));end if;

 if p_action='control' then
  if auth.role() is distinct from 'service_role' then raise exception 'operator_required' using errcode='42501'; end if;
  if jsonb_typeof(p_payload) is distinct from 'object' or (p_payload - array['paused','search_cap','detail_cap','comment_cap','scroll_cap','gap_seconds'])<>'{}'::jsonb
   or (p_payload ? 'paused' and jsonb_typeof(p_payload->'paused') is distinct from 'boolean') then raise exception 'invalid_control'; end if;
  if p_payload='{}'::jsonb then return (select to_jsonb(c)-'singleton' from crowd_v4.policy c where singleton); end if;
  update crowd_v4.policy set version=version+1,
   paused=coalesce((p_payload->>'paused')::boolean,paused),
   search_cap=coalesce((p_payload->>'search_cap')::int,search_cap), detail_cap=coalesce((p_payload->>'detail_cap')::int,detail_cap),
   comment_cap=coalesce((p_payload->>'comment_cap')::int,comment_cap), scroll_cap=coalesce((p_payload->>'scroll_cap')::int,scroll_cap),
   gap_seconds=coalesce((p_payload->>'gap_seconds')::int,gap_seconds) where singleton;
  insert into crowd_v4.audit(action,payload) values('control',p_payload);
  return (select to_jsonb(c)-'singleton' from crowd_v4.policy c where singleton);
 end if;
 if auth.role() is distinct from 'service_role' then raise exception 'service_only' using errcode='42501'; end if;
 if jsonb_typeof(p_payload) is distinct from 'object' then raise exception 'invalid_payload'; end if;
 if p_action='publish' then
  if jsonb_array_length(p_payload->'anchor_terms')<1 or exists(select 1 from jsonb_array_elements_text(p_payload->'anchor_terms') a(term) where length(term) not between 2 and 120) then raise exception 'invalid_anchors'; end if;
  insert into crowd_v4.tasks(source_key,query,store_name,restaurant_id,anchor_terms,target) values(p_payload->>'source_key',p_payload->>'query',p_payload->>'store_name',
   (p_payload->>'restaurant_id')::bigint,p_payload->'anchor_terms',coalesce((p_payload->>'target')::int,5)) on conflict(source_key) do nothing;
  select * into t from crowd_v4.tasks where source_key=p_payload->>'source_key';
  if t.query is distinct from p_payload->>'query' or t.anchor_terms is distinct from p_payload->'anchor_terms' then raise exception 'source_key_reused'; end if;
  result:=to_jsonb(t);
 elsif p_action in ('approve','suspend') then
  update crowd_v4.participants set status=case when p_action='approve' then 'approved' else 'suspended' end,
   quota_day=coalesce((p_payload->>'quota_day')::int,quota_day) where user_id=(p_payload->>'user_id')::uuid;
  if not found then raise exception 'participant_not_found'; end if;
  result:=jsonb_build_object('updated',true);
 elsif p_action='review' then
  -- Lock order is participant -> proof, shared with submit/reward accounting.
  select user_id into u from crowd_v4.proofs where id=(p_payload->>'proof_id')::bigint;
  if u is null then raise exception 'proof_not_found'; end if;
  perform 1 from crowd_v4.participants where user_id=u for update;
  select * into f from crowd_v4.proofs where id=(p_payload->>'proof_id')::bigint for update;
  decision:=p_payload->>'decision'; quote:=p_payload->>'quote';
  if decision not in ('verified','rejected') or decision is null or length(coalesce(p_payload->>'reason',''))<8 then raise exception 'review_reason_required'; end if;
  if f.status<>'received' then
   if f.status<>decision then raise exception 'review_is_final'; end if;
   return jsonb_build_object('status',f.status,'replayed',true);
  end if;
  if decision='verified' and (p_payload->>'public_visible' is distinct from 'true' or p_payload->>'relevant' is distinct from 'true'
   or p_payload->>'personal_experience' is distinct from 'true' or length(coalesce(quote,''))<8 or strpos(f.record->'evidence'->>'text',quote)=0
   or (p_payload->>'source_checked_at')::timestamptz is null or (p_payload->>'source_checked_at')::timestamptz>now()+interval '5 minutes'
   or (p_payload->>'source_checked_at')::timestamptz<f.received_at-interval '5 minutes') then raise exception 'strict_evidence_gate'; end if;
  update crowd_v4.proofs set status=decision,reviewed_at=now(),review_note=p_payload->>'reason',verified_quote=case when decision='verified' then quote end,
   source_checked_at=case when decision='verified' then (p_payload->>'source_checked_at')::timestamptz end where id=f.id;
  if decision='verified' then
   update crowd_v4.participants set verified_count=verified_count+1 where user_id=u returning verified_count into n;
   if n%100=0 then insert into crowd_v4.rewards(user_id,batch_no) values(u,n/100) on conflict do nothing; end if;
  end if;
  result:=jsonb_build_object('status',decision);
 elsif p_action='pay' then
  if length(coalesce(p_payload->>'reference',''))<4 then raise exception 'payment_reference_required'; end if;
  update crowd_v4.rewards set paid_at=now(),payment_reference=p_payload->>'reference' where user_id=(p_payload->>'user_id')::uuid and batch_no=(p_payload->>'batch_no')::int and paid_at is null;
  if not found then
   if not exists(select 1 from crowd_v4.rewards where user_id=(p_payload->>'user_id')::uuid and batch_no=(p_payload->>'batch_no')::int and payment_reference=p_payload->>'reference') then raise exception 'payment_not_found_or_conflict'; end if;
  end if;
  result:=jsonb_build_object('paid',true);
 elsif p_action='list' then
  if p_payload->>'kind'='participants' then select coalesce(jsonb_agg(to_jsonb(p)),'[]') into result from (select * from crowd_v4.participants order by joined_at limit 200) p;
  elsif p_payload->>'kind'='rewards' then select coalesce(jsonb_agg(to_jsonb(r)),'[]') into result from (select * from crowd_v4.rewards where paid_at is null order by created_at limit 200) r;
  else select coalesce(jsonb_agg(to_jsonb(proof_row)),'[]') into result from (select * from crowd_v4.proofs where status='received' order by id limit 100) proof_row; end if;
 elsif p_action='export' then
  select coalesce(jsonb_agg(jsonb_build_object('proof_id',proof_row.id,'note_id',proof_row.note_id,'record',proof_row.record,'verified_quote',proof_row.verified_quote,
   'source_checked_at',proof_row.source_checked_at,'store_name',task_row.store_name,'restaurant_id',task_row.restaurant_id,'query',task_row.query)),'[]') into result
   from (select * from crowd_v4.proofs where status='verified' and id>coalesce((p_payload->>'after_id')::bigint,0)
    and id<=coalesce((p_payload->>'through_id')::bigint,9223372036854775807) order by id limit 200) proof_row
   join crowd_v4.tasks task_row on task_row.id=proof_row.task_id;
 else raise exception 'unknown_action';
 end if;
 if p_action not in ('list','export') then insert into crowd_v4.audit(action,payload) values(p_action,p_payload); end if;
 return result;
end $function$
